import ghidra.app.script.GhidraScript;import java.nio.file.*;public class MetadataRefs extends GhidraScript {public void run()throws Exception{StringBuilder b=new StringBuilder();var it=currentProgram.getListing().getInstructions(true);while(it.hasNext()){var i=it.next();String s=i.toString();boolean hit=false;for(String n:new String[]{"-0x57e4(gp)","-0x57e0(gp)","-0x57dc(gp)","-0x57d8(gp)","-0x57d4(gp)","-0x57d0(gp)","-0x79d0(gp)","-0x79cc(gp)"})if(s.contains(n))hit=true;if(hit){var f=getFunctionContaining(i.getAddress());b.append(i.getAddress()+"\t"+(f==null?"none":f.getEntryPoint())+"\t"+s+"\n");}}Files.writeString(Path.of(getScriptArgs()[0]),b.toString());}}